const body = $input.first().json.body || $input.first().json;
const deal = body.current || body;

// Extraer campos del deal de Pipedrive
const title       = deal.title || '';
const dealId      = deal.id || '';
const personName  = deal.person_id?.name || deal.person_name || '';
const orgName     = deal.org_id?.name || deal.org_name || '';
const phone       = deal.person_id?.phone?.[0]?.value || '';
const email       = deal.person_id?.email?.[0]?.value || '';
const owner       = deal.owner_name || '';
const value       = deal.value || 0;
const currency    = deal.currency || 'EUR';
const stage       = deal.stage_id || '';
const source      = deal.utm_source || deal['768f7da5fddf46b896a73c8d8e2476cef7d6e89c'] || 'Desconocido';

// Campos personalizados del formulario web
const assetType     = deal.assetType || deal['assetType'] || '';
const assetWeight   = deal.assetWeight || '';
const assetEngine   = deal.assetEngine || deal.assetEngineDiésel || '';
const dateStart     = deal.dateStart || '';
const dateFinish    = deal.dateFinish || '';
const dateFlexible  = deal.dateFlexible || '';
const workLocation  = deal['Dirección del trabajo'] || deal.workLocation || '';
const razonSocial   = deal['Razón Social'] || deal.razonSocial || '';
const cif           = deal.CIF || '';
const rentType      = deal.rentType || '';
const precioTrato   = deal.precioTrato || deal.precio || 0;
const presupuesto   = deal['Rango precio alquiler'] || deal.presupuesto || '';

// Calcular duración en días
let duracionDias = null;
let duracionTexto = 'Desconocida';
if (dateStart && dateFinish) {
  const start = new Date(dateStart);
  const end   = new Date(dateFinish);
  duracionDias = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
  duracionTexto = duracionDias === 1 ? '1 día'
    : duracionDias <= 6 ? `${duracionDias} días`
    : duracionDias <= 30 ? `${Math.ceil(duracionDias/7)} semana(s)`
    : `${Math.ceil(duracionDias/30)} mes(es)`;
}

return [{ json: {
  dealId, title, personName, orgName, phone, email, owner,
  value, currency, stage, source,
  assetType, assetWeight, assetEngine,
  dateStart, dateFinish, dateFlexible,
  duracionDias, duracionTexto,
  workLocation, razonSocial, cif,
  rentType, precioTrato, presupuesto
} }];

