const email = $input.first().json;

const fromRaw    = email.from || '';
const senderEmail = fromRaw.match(/[\w.-]+@[\w.-]+\.\w+/)?.[0] || fromRaw;
const senderName  = fromRaw.replace(/<.*?>/, '').trim() || senderEmail.split('@')[0];
const subject     = email.subject || '(sin asunto)';
const body        = email.text || email.html?.replace(/<[^>]+>/g, ' ') || email.snippet || '(sin contenido)';
const messageId   = email.messageId || email.uid || String(Date.now());

return [{ json: {
  channel: 'email',
  senderEmail,
  senderName,
  subject,
  body: body.substring(0, 2000),
  messageId,
  receivedAt: email.date || new Date().toISOString()
} }];

const responseText = $json.content[0].text.trim();
let scoring;
try {
  const clean = responseText.replace(/```json|\n```|```/g, '').trim();
  scoring = JSON.parse(clean);
} catch(e) {
  scoring = { score: 5, tier: 'MEDIO', resumen: 'Error en evaluación.', fortalezas: '-', riesgos: 'Parse error', accion_recomendada: 'Revisar manualmente', urgencia: 'HOY', crear_deal_pipedrive: true };
}

const emailData = $('Extraer datos email').item.json;
return [{ json: { ...emailData, scoring } }];

